const englishCheckLabels={"最大迹误差":"Maximum trace error","最大厄米误差":"Maximum Hermiticity error","全轨迹最小本征值":"Minimum eigenvalue over the trajectory","Hamiltonian 厄米误差":"Hamiltonian Hermiticity error","时间步长（ns）":"Time step (ns)","正定性容差":"Positivity tolerance","数值方法":"Numerical method","T₂ 约定":"T₂ convention"};
import {esc,num,table,notes,sources,controlsHTML,readControls} from './pathways-views.js?v=20261110-en1';
import {quantumCurveSVG,heatmapSVG} from './quantum-plots.js?v=20261110-en1';
import {svgMathText} from './math-svg.js?v=20261110-en1';
export {esc,num,table,notes,sources,controlsHTML,readControls};
const val=x=>typeof x==='number'?num(x):x===null||x===undefined?'—':typeof x==='object'?JSON.stringify(x):String(x);
const transitionLabel=x=>({addition:"Add electronics",removal:"Remove electrons",response:"connectivity response"}[x]||x);
const safeId=s=>String(s).replace(/[^a-zA-Z0-9_-]/g,'-');
const complex=(re,im)=>num(re)+(im<0?'':' + ')+num(im)+'i';

export function blochSVG(v,yaw=35){
 const a=yaw*Math.PI/180,xy=([x,y,z])=>[230+120*(Math.cos(a)*x-Math.sin(a)*y),170-120*z+40*(Math.sin(a)*x+Math.cos(a)*y)];
 const end=xy(v);
 return `<svg viewBox="0 0 460 350" role="img" aria-label="Bloch vector of the current reduced spin"><circle cx="230" cy="170" r="120" fill="#f2f7f3" stroke="#92aa9c"/><ellipse cx="230" cy="170" rx="120" ry="40" fill="none" stroke="#b5c8bc" stroke-dasharray="5 5"/>${[[[1.2,0,0],'x'],[[0,1.2,0],'y'],[[0,0,1.2],'z']].map(([p,t])=>{const q=xy(p);return `<line x1="230" y1="170" x2="${q[0]}" y2="${q[1]}" stroke="#8da699"/><text x="${q[0]+5}" y="${q[1]}">${t}</text>`;}).join('')}<line x1="230" y1="170" x2="${end[0]}" y2="${end[1]}" stroke="#237863" stroke-width="5"/><circle cx="${end[0]}" cy="${end[1]}" r="7" fill="#a56b31"/><text x="230" y="329" text-anchor="middle">(${v.map(num).join(', ')})</text></svg>`;
}

export function transitionSticks(rows,selected=0){
 if(!rows.length)return "<p>The selected probe has no non-zero transitions.</p>";
 const min=Math.min(...rows.map(t=>t.energy)),max=Math.max(...rows.map(t=>t.energy)),span=max-min||1,top=Math.max(...rows.map(t=>t.weight),1e-12);
 return `<svg viewBox="0 0 720 300" role="img" aria-label="Clickable discrete transition spectrum; vertical line height is weight rather than broadened peak height"><path d="M70 30V240H660" fill="none" stroke="#9cb5a6"/>${rows.map((t,i)=>{const x=90+550*(t.energy-min)/span,y=240-180*t.weight/top;return `<g><line x1="${x}" x2="${x}" y1="240" y2="${y}" stroke="${i===selected?'#b37530':'#287b64'}" stroke-width="${i===selected?6:3}"/><circle data-br-transition="${i}" tabindex="0" role="button" aria-label="Leap ${i+1}: Energy ${num(t.energy)} eV, weight ${num(t.weight)}" cx="${x}" cy="${y}" r="9" fill="${i===selected?'#b37530':'#287b64'}"><title>transition${i+1}；E=${num(t.energy)}；w=${num(t.weight)}</title></circle></g>`;}).join('')}<text x="80" y="270">${num(min)}</text><text x="650" y="270" text-anchor="end">${num(max)}</text><text x="360" y="293" text-anchor="middle">E (eV); zero-width discrete weight</text></svg>`;
}

function formulaCards(r){return `<section class="br-formulas"><h3>formula is linked to the current result</h3><p>Click the formula to search for words and highlight the corresponding graphics; the button can directly locate the graphics. The values ​​are from the current calculation.</p>${(r.formulaLinks||[]).map(f=>`<article class="br-formula-card" data-formula-context="${safeId(f.id)}" data-plot-target="${safeId(f.plot)}"><h4>${esc(f.label)}</h4><div class="obs-formula">${esc(f.formula)}</div><p>${esc(f.meaning)}</p><div class="br-current-values">${table(["Current calculation amount","value"],(f.values||[]).map(v=>[v.label,val(v.value)]))}</div><button type="button" class="secondary" data-br-focus="${safeId(f.plot)}">positioning corresponding graphics</button></article>`).join('')}</section>`;}
export function resultHTML(module,r){
 let special='';
 if(module==='manybody')special="<section class=\"br-visual\"><h3>Click on the peak to track the transition</h3><div id=\"br-sticks\"></div><label>Select transition<select id=\"br-transition\"></select></label><div id=\"br-transition-info\"></div></section>";
 if(module==='density')special="<section class=\"br-visual\"><h3>time, Bloch vector and density matrix linkage</h3><label>track time<input id=\"br-time\" type=\"range\" min=\"0\" max=\""+(r.stateSnapshots.length-1)+"\" value=\"0\" step=\"1\"></label><label>viewing direction<input id=\"br-yaw\" type=\"range\" min=\"0\" max=\"360\" value=\"35\"></label><label>matrix component<select id=\"br-component\"><option value=\"re\">real part</option><option value=\"im\">imaginary part</option></select></label><div id=\"br-state-info\"></div><div class=\"br-state-grid\"><div id=\"br-bloch\"></div><div id=\"br-matrix\"></div></div></section>";
 if(module==='polaron')special="<section class=\"br-visual\"><h3>Electronics and Vibration Cloud</h3><label>displays vibration displacement<select id=\"br-cloud-kind\"><option value=\"unconditional\">unconditional average displacement</option><option value=\"site0\">The conditional displacement of the electron at site 0</option><option value=\"site1\">The conditional displacement of the electron at site 1</option></select></label><div id=\"br-cloud\"></div><p>The size of the circle represents electron occupation, and the endpoints of the displacement line represent dimensionless vibration coordinates. Conditional shifts are filtered by measured electron positions and do not indicate that static spontaneous localization has occurred.</p></section>";
 if(module==='workshop')special=`<section class="br-visual"><h3>View generator constraints step by step</h3><p>enable operation:${esc(r.workshop.generators.join('；')||"None generator constraint")}</p><label>selection coefficient relationship<select id="br-constraint">${r.workshop.constraints.map((_,i)=>`<option value="${i}">constraint ${i+1}</option>`).join('')}</select></label><div id="br-constraint-info"></div><p>Matrix identity → Monomial coefficient relationship → Allowed space → Projected energy band. The linear relationships shown may be mutually dependent; the number of independent constraints is given by the matrix rank.</p></section>`;
 return table(["Current results","value"],r.summary.map(s=>[s.label,val(s.value)+(s.unit?' '+s.unit:'')]))+special+formulaCards(r)+r.plots.map((p,i)=>`<section class="br-plot" data-br-plot="${safeId(p.id||String(i))}" tabindex="-1"><h3>${esc(p.title)}</h3>${quantumCurveSVG(p.series,{xLabel:p.xLabel,yLabel:p.yLabel})}</section>`).join('')+r.tables.map(t=>`<details><summary>${esc(t.title)}</summary>${table(t.columns,t.rows.map(row=>row.map(val)))}</details>`).join('')+`<details><summary>Numerical verification and convention</summary>${table(["check item","results"],Object.entries(r.checks||{}).map(([k,v])=>[englishCheckLabels[k]||k,val(v)]))}</details>`+notes(r.warnings||[]);
}

export function bindResult(module,r,root){
 const $=s=>root.querySelector(s);
 const focusPlot=(id,scroll=true)=>{root.querySelectorAll('[data-br-plot]').forEach(el=>el.setAttribute('data-highlighted',String(el.dataset.brPlot===id)));const target=$('[data-br-plot="'+id+'"]');if(scroll){target?.scrollIntoView?.({behavior:'smooth',block:'center'});target?.focus?.({preventScroll:true});}};
 root.querySelectorAll('[data-br-focus]').forEach(b=>b.onclick=()=>focusPlot(b.dataset.brFocus));
 root.querySelectorAll('[data-formula-context]').forEach(card=>card.onclick=e=>{if(e.target?.closest?.('[data-fd-trigger]'))focusPlot(card.dataset.plotTarget,false);});
 if(module==='manybody'){
  const rows=r.transitions||[],select=$('#br-transition');select.innerHTML=rows.map((t,i)=>`<option value="${i}">${i+1} · ${esc(transitionLabel(t.kind))} · ${num(t.energy)} eV · w=${num(t.weight)}</option>`).join('');
  const draw=()=>{const i=Number(select.value)||0,t=rows[i];$('#br-sticks').innerHTML=transitionSticks(rows,i);if(!t){$('#br-transition-info').textContent="is nothing but zero transition";return;}$('#br-transition-info').innerHTML=table(["transition information","current value"],[["process",transitionLabel(t.kind)],["Initial state energy / eV",num(t.initialEnergy)],["Final state energy / eV",num(t.finalEnergy)],["Number of initial state electrons",t.initialParticles],["Number of electrons in the final state",t.finalParticles],["Initial state/final state degeneracy",t.initialDegeneracy+' / '+t.finalDegeneracy],["discrete spectrum weight",num(t.weight)],["Initial site density",t.initialObservables.density.map(num).join(', ')],["Conditional final site density",t.finalObservables.density.map(num).join(', ')]])+`<p>${esc(t.finalObservablesConvention)}</p>`;root.querySelectorAll('[data-br-transition]').forEach(b=>{const choose=()=>{select.value=b.dataset.brTransition;draw();};b.onclick=choose;b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose();}};});};select.onchange=draw;draw();
 }
 if(module==='density'){
  const draw=()=>{const s=r.stateSnapshots[Number($('#br-time').value)],component=$('#br-component').value;$('#br-state-info').innerHTML=table(["current time","value"],[["time/ns",num(s.time)],["overall purity",num(s.purity)],["Spin A reduced entropy (bit)",num(s.entropyA)],["double spin negativity",val(s.negativity)]]);$('#br-bloch').innerHTML=blochSVG(s.blochA,Number($('#br-yaw').value));const n=s.rho.re.length;$('#br-matrix').innerHTML=heatmapSVG(Array.from({length:n},(_,i)=>i),Array.from({length:n},(_,i)=>i),s.rho[component],{title:"ρ of"+(component==='re'?"real part":"imaginary part"),signed:true,xLabel:"Column basis vector index",yLabel:"row basis index"})+`<p>Base:${esc(r.basis.join('，'))}. Bloch The ball shows the reduced state of spin A.</p>`;};$('#br-time').oninput=draw;$('#br-yaw').oninput=draw;$('#br-component').onchange=draw;draw();
 }
 if(module==='polaron'){
  const g=r.ground,draw=()=>{const kind=$('#br-cloud-kind').value,displacement=kind==='unconditional'?g.displacement:g.conditionalDisplacement[Number(kind.at(-1))];const scale=Math.max(1,...displacement.filter(x=>typeof x==='number').map(Math.abs));$('#br-cloud').innerHTML=`<svg viewBox="0 0 600 260" role="img" aria-label="Electron occupation and conditional vibration displacement diagram">${[0,1].map(i=>{const x=160+280*i,dx=displacement[i],end=x+(dx===null?0:65*dx/scale);return `<line x1="${x-80}" x2="${x+80}" y1="130" y2="130" stroke="#c3d1c8"/><line x1="${x}" x2="${end}" y1="130" y2="130" stroke="#aa7b39" stroke-width="5"/><circle cx="${end}" cy="130" r="${12+25*Math.sqrt(Math.max(0,g.density[i]))}" fill="#2c7f69"/><text x="${x}" y="45" text-anchor="middle">site ${i}：n=${num(g.density[i])}</text><text x="${x}" y="210" text-anchor="middle">X=${val(dx)}；N=${num(g.phononOccupation[i])}</text>`;}).join('')}</svg><p>The displacement display ratio is normalized according to the current maximum absolute value; the specific value is subject to the mark above.</p>`;};$('#br-cloud-kind').onchange=draw;draw();
 }
 if(module==='workshop'){
  const draw=()=>{const row=r.workshop.constraints[Number($('#br-constraint').value)];$('#br-constraint-info').innerHTML=row?`<div class="obs-formula">${esc(row.map(x=>num(x.factor)+' '+x.coefficient).join(' + ')+' = 0')}</div>`:"<p>generator is not enabled, and all 24 real coefficients can take on free values.</p>";};$('#br-constraint').onchange=draw;draw();
 }
}
